package com.prayerkey.manna.data

import kotlinx.datetime.Clock
import kotlinx.datetime.TimeZone
import kotlinx.datetime.todayIn
import com.prayerkey.manna.model.DailyPrayer
import kotlinx.datetime.LocalDate

/*
 * A short prayer for each hour of the day - morning, afternoon, evening,
 * night and midnight - thirty-one of each, so a month goes by without one
 * repeating. Written for their hour: the evening prayer gives the day back,
 * the night prayer lets it go, the midnight prayer keeps watch.
 */

private val MORNING = listOf(
    DailyPrayer(ref = "Psalm 5:3", title = "Before the Day Begins", verse = "My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.", prayer = "Lord, before the noise begins, I am here. You hear me first. Order my steps, guard my words, and let me carry You into every room today. Amen."),
    DailyPrayer(ref = "Lamentations 3:23", title = "New Mercy", verse = "They are new every morning: great is thy faithfulness.", prayer = "Father, yesterday is finished and Your mercy is new. Let me begin clean, without dragging the old weight into this day. Amen."),
    DailyPrayer(ref = "Psalm 118:24", title = "This Is the Day", verse = "This is the day which the LORD hath made; we will rejoice and be glad in it.", prayer = "Lord, this day is Yours before it is mine. Help me to be glad in it, even if it is ordinary. Amen."),
    DailyPrayer(ref = "Psalm 143:8", title = "Show Me the Way", verse = "Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.", prayer = "Father, I do not know everything this day holds. You do. Show me the way, and give me the grace to walk in it. Amen."),
    DailyPrayer(ref = "Isaiah 40:31", title = "Strength for Today", verse = "But they that wait upon the LORD shall renew their strength; they shall mount up with wings as eagles; they shall run, and not be weary; and they shall walk, and not faint.", prayer = "Lord, I woke up tired. Renew my strength for what is in front of me today, one step at a time. Amen."),
    DailyPrayer(ref = "Matthew 6:33", title = "First Things First", verse = "But seek ye first the kingdom of God, and his righteousness; and all these things shall be added unto you.", prayer = "Father, before the list, before the messages, I seek You. Put my day in its right order. Amen."),
    DailyPrayer(ref = "Psalm 141:3", title = "Guard My Mouth", verse = "Set a watch, O LORD, before my mouth; keep the door of my lips.", prayer = "Lord, keep my words kind today. Let me build people up, and hold back what would wound them. Amen."),
    DailyPrayer(ref = "Psalm 31:15", title = "Into Your Hands", verse = "My times are in thy hand: deliver me from the hand of mine enemies, and from them that persecute me.", prayer = "Father, I place today in Your hands: the meetings, the tasks, the people. Let nothing reach me that has not passed through You. Amen."),
    DailyPrayer(ref = "Ephesians 5:18", title = "Fill Me", verse = "And be not drunk with wine, wherein is excess; but be filled with the Spirit;", prayer = "Holy Spirit, fill me this morning. Let what flows out of me today come from You and not from my mood. Amen."),
    DailyPrayer(ref = "James 1:5", title = "Wisdom for Today", verse = "If any of you lack wisdom, let him ask of God, that giveth to all men liberally, and upbraideth not; and it shall be given him.", prayer = "Lord, I will face decisions today I cannot foresee. Give me wisdom when I need it, and humility to take it. Amen."),
    DailyPrayer(ref = "Psalm 119:105", title = "Light My Path", verse = "Thy word is a lamp unto my feet, and a light unto my path.", prayer = "Father, give me enough light for today's steps. I do not need to see the whole road, only the next part of it. Amen."),
    DailyPrayer(ref = "Psalm 51:12", title = "A Willing Heart", verse = "Restore unto me the joy of thy salvation; and uphold me with thy free spirit.", prayer = "Lord, make me willing today: to serve, to listen, to forgive, to obey when it costs me something. Amen."),
    DailyPrayer(ref = "Deuteronomy 31:8", title = "Walk With Me", verse = "And the LORD, he it is that doth go before thee; he will be with thee, he will not fail thee, neither forsake thee: fear not, neither be dismayed.", prayer = "Father, You have already gone ahead into this day. Walk with me through every part of it. Amen."),
    DailyPrayer(ref = "John 14:27", title = "Be My Peace", verse = "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.", prayer = "Jesus, before worry finds me, let Your peace find me first. Keep my heart steady whatever comes. Amen."),
    DailyPrayer(ref = "Nehemiah 8:10", title = "Give Me Joy", verse = "Then he said unto them, Go your way, eat the fat, and drink the sweet, and send portions unto them for whom nothing is prepared: for this day is holy unto our Lord: neither be ye sorry; for the joy of the LORD is your strength.", prayer = "Lord, let joy in You be my strength today, not the ease of the day or the approval of others. Amen."),
    DailyPrayer(ref = "Psalm 119:18", title = "Open My Eyes", verse = "Open thou mine eyes, that I may behold wondrous things out of thy law.", prayer = "Father, open my eyes today to see You at work, and to see the people I would otherwise pass by. Amen."),
    DailyPrayer(ref = "Luke 16:10", title = "Faithful in Small Things", verse = "He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.", prayer = "Lord, help me do the small, ordinary things of today faithfully and well, as if I were doing them for You. Amen."),
    DailyPrayer(ref = "Isaiah 41:10", title = "I Am Not Alone", verse = "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.", prayer = "Father, whatever I face today, I do not face it alone. Hold my right hand and steady me. Amen."),
    DailyPrayer(ref = "Genesis 12:2", title = "Make Me a Blessing", verse = "And I will make of thee a great nation, and I will bless thee, and make thy name great; and thou shalt be a blessing:", prayer = "Lord, bless me today so that I can be a blessing. Show me one person to encourage before the day ends. Amen."),
    DailyPrayer(ref = "Colossians 3:12", title = "Teach Me Patience", verse = "Put on therefore, as the elect of God, holy and beloved, bowels of mercies, kindness, humbleness of mind, meekness, longsuffering;", prayer = "Father, dress me in patience today, especially with the person who tests it most. Amen."),
    DailyPrayer(ref = "Matthew 6:10", title = "Your Will Today", verse = "Thy kingdom come. Thy will be done in earth, as it is in heaven.", prayer = "Lord, let Your will be done in my day, even where it differs from my plans. I trust Yours more. Amen."),
    DailyPrayer(ref = "Psalm 51:10", title = "Clean Heart", verse = "Create in me a clean heart, O God; and renew a right spirit within me.", prayer = "Father, begin this day by making my heart clean. Keep me from carrying yesterday's resentment into today. Amen."),
    DailyPrayer(ref = "Joshua 1:9", title = "Courage", verse = "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.", prayer = "Lord, give me courage for the hard conversation, the difficult task, and the step I have been avoiding. Amen."),
    DailyPrayer(ref = "1 Samuel 3:10", title = "Speak, Lord", verse = "And the LORD came, and stood, and called as at other times, Samuel, Samuel. Then Samuel answered, Speak; for thy servant heareth.", prayer = "Father, speak to me today, and make me quiet enough to hear You above the noise. Amen."),
    DailyPrayer(ref = "Matthew 6:11", title = "Enough for Today", verse = "Give us this day our daily bread.", prayer = "Lord, give me what I need for today, and keep me from worrying about what tomorrow needs. Amen."),
    DailyPrayer(ref = "Philippians 4:4", title = "Rejoice", verse = "Rejoice in the Lord alway: and again I say, Rejoice.", prayer = "Father, I choose to rejoice in You this morning, before I know how the day will go. Amen."),
    DailyPrayer(ref = "Psalm 121:8", title = "Protect My Home", verse = "The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.", prayer = "Lord, watch over my family as we go out today. Keep us safe, and bring us home to one another. Amen."),
    DailyPrayer(ref = "Colossians 3:23", title = "Serve Well", verse = "And whatsoever ye do, do it heartily, as to the Lord, and not unto men;", prayer = "Father, let my work today be honest and wholehearted, done for You and not for applause. Amen."),
    DailyPrayer(ref = "John 13:34", title = "Love Well", verse = "A new commandment I give unto you, That ye love one another; as I have loved you, that ye also love one another.", prayer = "Jesus, help me love the people in front of me today as You have loved me. Amen."),
    DailyPrayer(ref = "Proverbs 3:5", title = "Trust", verse = "Trust in the LORD with all thine heart; and lean not unto thine own understanding.", prayer = "Lord, I do not understand everything, and I do not have to. Today I will trust You with all of it. Amen."),
    DailyPrayer(ref = "Psalm 92:2", title = "Thank You for Morning", verse = "To shew forth thy lovingkindness in the morning, and thy faithfulness every night,", prayer = "Father, thank You for waking me, for breath, and for another day to know You. Amen."),
)

private val AFTERNOON = listOf(
    DailyPrayer(ref = "Psalm 55:17", title = "A Pause at Midday", verse = "Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice.", prayer = "Lord, I stop in the middle of this day to remember You. Steady me for the hours that are left. Amen."),
    DailyPrayer(ref = "Isaiah 40:29", title = "Renewed Strength", verse = "He giveth power to the faint; and to them that have no might he increaseth strength.", prayer = "Father, my energy is running low. Renew me for the rest of this day. Amen."),
    DailyPrayer(ref = "Psalm 139:23", title = "Reset My Heart", verse = "Search me, O God, and know my heart: try me, and know my thoughts:", prayer = "Lord, if this morning has soured my heart, reset it now. Give me a fresh start for the afternoon. Amen."),
    DailyPrayer(ref = "Galatians 5:22", title = "Patience Again", verse = "But the fruit of the Spirit is love, joy, peace, longsuffering, gentleness, goodness, faith,", prayer = "Father, my patience is thinner than it was this morning. Fill it up again, for the people still ahead of me today. Amen."),
    DailyPrayer(ref = "Psalm 16:8", title = "Right Where I Am", verse = "I have set the LORD always before me: because he is at my right hand, I shall not be moved.", prayer = "Lord, in the middle of the work, I turn my eyes to You. Keep me aware that You are near. Amen."),
    DailyPrayer(ref = "1 Peter 5:7", title = "Carry It for Me", verse = "Casting all your care upon him; for he careth for you.", prayer = "Father, I hand You what has been building up since this morning. Carry it, so I can keep going. Amen."),
    DailyPrayer(ref = "Proverbs 2:6", title = "Wisdom for the Rest", verse = "For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.", prayer = "Lord, give me wisdom for the decisions still waiting this afternoon. Amen."),
    DailyPrayer(ref = "Proverbs 15:1", title = "Gentle Words", verse = "A soft answer turneth away wrath: but grievous words stir up anger.", prayer = "Father, if I am tired and short with people, soften my words before they leave my mouth. Amen."),
    DailyPrayer(ref = "Galatians 6:9", title = "Finish Well", verse = "And let us not be weary in well doing: for in due season we shall reap, if we faint not.", prayer = "Lord, help me finish today's work well, not just finish it. Amen."),
    DailyPrayer(ref = "Matthew 28:20", title = "You Are Here", verse = "Teaching them to observe all things whatsoever I have commanded you: and, lo, I am with you alway, even unto the end of the world. Amen.", prayer = "Jesus, You are with me in this afternoon as much as in the quiet of the morning. Thank You. Amen."),
    DailyPrayer(ref = "Psalm 46:10", title = "Breathe", verse = "Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.", prayer = "Father, for this moment I stop and breathe. You are God, and I do not have to hold everything together. Amen."),
    DailyPrayer(ref = "Colossians 3:2", title = "Focus", verse = "Set your affection on things above, not on things on the earth.", prayer = "Lord, my attention is scattered. Gather it and set it on what matters for the rest of today. Amen."),
    DailyPrayer(ref = "1 John 1:9", title = "Mercy for Mistakes", verse = "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.", prayer = "Father, I have already got things wrong today. Forgive me, and let me carry on without the weight of it. Amen."),
    DailyPrayer(ref = "Ephesians 4:32", title = "Kind to Someone", verse = "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you.", prayer = "Lord, show me someone this afternoon who needs a kind word, and give me the words. Amen."),
    DailyPrayer(ref = "2 Corinthians 12:9", title = "Enough", verse = "And he said unto me, My grace is sufficient for thee: for my strength is made perfect in weakness. Most gladly therefore will I rather glory in my infirmities, that the power of Christ may rest upon me.", prayer = "Father, I feel stretched thin. Your grace is enough for the rest of this day. Amen."),
    DailyPrayer(ref = "Psalm 121:7", title = "Protect the Road Home", verse = "The LORD shall preserve thee from all evil: he shall preserve thy soul.", prayer = "Lord, keep everyone I love safe on their way through today and on the road home. Amen."),
    DailyPrayer(ref = "1 Thessalonians 5:18", title = "Thankful at Noon", verse = "In every thing give thanks: for this is the will of God in Christ Jesus concerning you.", prayer = "Father, halfway through this day, I stop to thank You for what has already gone right. Amen."),
    DailyPrayer(ref = "Philippians 4:8", title = "Guard My Mind", verse = "Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.", prayer = "Lord, keep my thoughts clean and true this afternoon, and away from worry and comparison. Amen."),
    DailyPrayer(ref = "Isaiah 26:3", title = "Steady Me", verse = "Thou wilt keep him in perfect peace, whose mind is stayed on thee: because he trusteth in thee.", prayer = "Father, the afternoon is busy and my heart is racing. Keep me in Your peace. Amen."),
    DailyPrayer(ref = "Psalm 90:17", title = "For My Work", verse = "And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.", prayer = "Lord, establish the work of my hands today. Let something good come of it. Amen."),
    DailyPrayer(ref = "Joshua 1:9", title = "Courage to Continue", verse = "Have not I commanded thee? Be strong and of a good courage; be not afraid, neither be thou dismayed: for the LORD thy God is with thee whithersoever thou goest.", prayer = "Father, give me courage for what is still left undone today. Amen."),
    DailyPrayer(ref = "Luke 16:10", title = "Faithful in the Middle", verse = "He that is faithful in that which is least is faithful also in much: and he that is unjust in the least is unjust also in much.", prayer = "Lord, the middle of the day is where faithfulness is tested. Keep me faithful in the small things. Amen."),
    DailyPrayer(ref = "Matthew 11:28", title = "Rest in You", verse = "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", prayer = "Jesus, I come to You for rest in the middle of the day. Refresh me. Amen."),
    DailyPrayer(ref = "1 Corinthians 13:4", title = "Love at Work", verse = "Charity suffereth long, and is kind; charity envieth not; charity vaunteth not itself, is not puffed up,", prayer = "Father, let love show up in how I treat the people I work beside this afternoon. Amen."),
    DailyPrayer(ref = "Philippians 2:3", title = "Humble Me", verse = "Let nothing be done through strife or vainglory; but in lowliness of mind let each esteem other better than themselves.", prayer = "Lord, keep me humble this afternoon, quick to listen and slow to prove myself right. Amen."),
    DailyPrayer(ref = "Psalm 27:14", title = "Wait on You", verse = "Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD.", prayer = "Father, some of what I hoped for today has not come. Help me wait on You without anxiety. Amen."),
    DailyPrayer(ref = "John 8:12", title = "Light in the Afternoon", verse = "Then spake Jesus again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.", prayer = "Jesus, if the day has grown heavy, be my light through the rest of it. Amen."),
    DailyPrayer(ref = "Psalm 91:11", title = "Hold My Family", verse = "For he shall give his angels charge over thee, to keep thee in all thy ways.", prayer = "Lord, wherever my family is this afternoon, watch over them and keep them. Amen."),
    DailyPrayer(ref = "Psalm 16:11", title = "Joy Again", verse = "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.", prayer = "Father, restore my joy for the rest of the day. Let it come from You and not from how things are going. Amen."),
    DailyPrayer(ref = "John 14:15", title = "Obey Now", verse = "If ye love me, keep my commandments.", prayer = "Lord, if there is something You asked of me this morning that I have not done, give me the will to do it now. Amen."),
    DailyPrayer(ref = "Psalm 100:3", title = "Still Yours", verse = "Know ye that the LORD he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture.", prayer = "Father, however this day is going, I am still Yours. Let that steady me until evening. Amen."),
)

private val EVENING = listOf(
    DailyPrayer(ref = "Psalm 141:2", title = "As the Day Closes", verse = "Let my prayer be set forth before thee as incense; and the lifting up of my hands as the evening sacrifice.", prayer = "Lord, as this day closes, I bring it back to You: what went well, what did not, and everything in between. Amen."),
    DailyPrayer(ref = "Psalm 92:1", title = "Thank You for Today", verse = "It is a good thing to give thanks unto the LORD, and to sing praises unto thy name, O most High:", prayer = "Father, thank You for carrying me through today. I did not do it alone. Amen."),
    DailyPrayer(ref = "1 John 1:9", title = "What I Got Wrong", verse = "If we confess our sins, he is faithful and just to forgive us our sins, and to cleanse us from all unrighteousness.", prayer = "Lord, forgive what I got wrong today. Let me not carry it into tomorrow. Amen."),
    DailyPrayer(ref = "Psalm 34:8", title = "Where I Saw You", verse = "O taste and see that the LORD is good: blessed is the man that trusteth in him.", prayer = "Father, open my eyes to where You were today, in the ordinary moments I nearly missed. Amen."),
    DailyPrayer(ref = "Psalm 55:22", title = "Release the Day", verse = "Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.", prayer = "Lord, I release this day into Your hands. What is unfinished can wait until morning. Amen."),
    DailyPrayer(ref = "Psalm 127:1", title = "Home", verse = "Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain.", prayer = "Father, bless this home tonight. Let peace settle over everyone under this roof. Amen."),
    DailyPrayer(ref = "Ephesians 4:32", title = "Forgive Them Too", verse = "And be ye kind one to another, tenderhearted, forgiving one another, even as God for Christ's sake hath forgiven you.", prayer = "Lord, if someone hurt me today, help me forgive them before I sleep. Amen."),
    DailyPrayer(ref = "John 14:27", title = "Peace Tonight", verse = "Peace I leave with you, my peace I give unto you: not as the world giveth, give I unto you. Let not your heart be troubled, neither let it be afraid.", prayer = "Jesus, quiet my heart this evening. Let Your peace replace the noise of the day. Amen."),
    DailyPrayer(ref = "Lamentations 3:22", title = "Faithful Again", verse = "It is of the LORD'S mercies that we are not consumed, because his compassions fail not.", prayer = "Father, You were faithful again today. Thank You that Your compassion did not run out. Amen."),
    DailyPrayer(ref = "Matthew 11:28", title = "Rest for the Weary", verse = "Come unto me, all ye that labour and are heavy laden, and I will give you rest.", prayer = "Jesus, I am tired. Give me rest tonight, in body and in soul. Amen."),
    DailyPrayer(ref = "Psalm 113:3", title = "Evening Praise", verse = "From the rising of the sun unto the going down of the same the LORD'S name is to be praised.", prayer = "Lord, from morning to now, You are worthy of praise. I end the day by praising You. Amen."),
    DailyPrayer(ref = "Philippians 4:8", title = "The Good in Today", verse = "Finally, brethren, whatsoever things are true, whatsoever things are honest, whatsoever things are just, whatsoever things are pure, whatsoever things are lovely, whatsoever things are of good report; if there be any virtue, and if there be any praise, think on these things.", prayer = "Father, help me remember the good things from today, not only the hard ones. Amen."),
    DailyPrayer(ref = "Matthew 6:34", title = "Tomorrow Is Yours", verse = "Take therefore no thought for the morrow: for the morrow shall take thought for the things of itself. Sufficient unto the day is the evil thereof.", prayer = "Lord, tomorrow belongs to You. I will not borrow its worries tonight. Amen."),
    DailyPrayer(ref = "Psalm 128:3", title = "For My Family", verse = "Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table.", prayer = "Father, bless my family tonight. Heal what is strained, and draw us closer to You. Amen."),
    DailyPrayer(ref = "Psalm 147:3", title = "Heal the Hurt", verse = "He healeth the broken in heart, and bindeth up their wounds.", prayer = "Lord, if something wounded me today, begin to heal it tonight. Amen."),
    DailyPrayer(ref = "Psalm 90:12", title = "Lessons Learned", verse = "So teach us to number our days, that we may apply our hearts unto wisdom.", prayer = "Father, teach me something from today, so that tomorrow I live a little wiser. Amen."),
    DailyPrayer(ref = "Psalm 86:11", title = "Undivided", verse = "Teach me thy way, O LORD; I will walk in thy truth: unite my heart to fear thy name.", prayer = "Lord, I was pulled in many directions today. Gather my heart back to You tonight. Amen."),
    DailyPrayer(ref = "Psalm 139:12", title = "Light in Darkness", verse = "Yea, the darkness hideth not from thee; but the night shineth as the day: the darkness and the light are both alike to thee.", prayer = "Father, as the light fades, remind me that darkness is not dark to You. Amen."),
    DailyPrayer(ref = "Psalm 131:2", title = "A Quiet Heart", verse = "Surely I have behaved and quieted myself, as a child that is weaned of his mother: my soul is even as a weaned child.", prayer = "Lord, quiet my heart like a child at rest. I do not need to solve everything tonight. Amen."),
    DailyPrayer(ref = "Psalm 139:24", title = "Evening Confession", verse = "And see if there be any wicked way in me, and lead me in the way everlasting.", prayer = "Father, show me anything in me today that grieved You, and lead me back to Your way. Amen."),
    DailyPrayer(ref = "Philippians 1:3", title = "Thank You for People", verse = "I thank my God upon every remembrance of you,", prayer = "Lord, thank You for the people I shared today with. Bless each of them tonight. Amen."),
    DailyPrayer(ref = "2 Corinthians 9:8", title = "Enough Was Enough", verse = "And God is able to make all grace abound toward you; that ye, always having all sufficiency in all things, may abound to every good work:", prayer = "Father, You gave me enough for today. Thank You for Your provision. Amen."),
    DailyPrayer(ref = "Hebrews 12:1", title = "Lay It Down", verse = "Wherefore seeing we also are compassed about with so great a cloud of witnesses, let us lay aside every weight, and the sin which doth so easily beset us, and let us run with patience the race that is set before us,", prayer = "Lord, I lay down what I have been carrying all day. I will not take it to bed. Amen."),
    DailyPrayer(ref = "Psalm 91:1", title = "Protection Tonight", verse = "He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.", prayer = "Father, cover my home and my family tonight. Let us rest under Your shadow. Amen."),
    DailyPrayer(ref = "Colossians 3:15", title = "Grateful Heart", verse = "And let the peace of God rule in your hearts, to the which also ye are called in one body; and be ye thankful.", prayer = "Lord, end my day with gratitude instead of complaint. Thank You for today. Amen."),
    DailyPrayer(ref = "Isaiah 41:10", title = "Still Held", verse = "Fear thou not; for I am with thee: be not dismayed; for I am thy God: I will strengthen thee; yea, I will help thee; yea, I will uphold thee with the right hand of my righteousness.", prayer = "Father, whatever today was, You held me through it. Thank You. Amen."),
    DailyPrayer(ref = "Ezekiel 36:26", title = "Soft Heart", verse = "A new heart also will I give you, and a new spirit will I put within you: and I will take away the stony heart out of your flesh, and I will give you an heart of flesh.", prayer = "Lord, if today hardened me, soften my heart again before I sleep. Amen."),
    DailyPrayer(ref = "Psalm 16:11", title = "Your Presence", verse = "Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.", prayer = "Father, let me end this day aware of Your presence, and rest in it. Amen."),
    DailyPrayer(ref = "Colossians 3:16", title = "Word to Carry", verse = "Let the word of Christ dwell in you richly in all wisdom; teaching and admonishing one another in psalms and hymns and spiritual songs, singing with grace in your hearts to the Lord.", prayer = "Lord, let one word from You stay with me through the night. Amen."),
    DailyPrayer(ref = "Romans 12:1", title = "Evening Offering", verse = "I beseech you therefore, brethren, by the mercies of God, that ye present your bodies a living sacrifice, holy, acceptable unto God, which is your reasonable service.", prayer = "Father, I offer You today, all of it, as imperfect as it was. Receive it. Amen."),
    DailyPrayer(ref = "Psalm 4:8", title = "Good Night, Father", verse = "I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.", prayer = "Lord, I end this day with You. Watch over the night, and meet me in the morning. Amen."),
)

private val NIGHT = listOf(
    DailyPrayer(ref = "Psalm 4:8", title = "Before I Sleep", verse = "I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.", prayer = "Lord, I lie down in peace tonight, because You keep watch. Let me rest. Amen."),
    DailyPrayer(ref = "Psalm 121:4", title = "He Does Not Sleep", verse = "Behold, he that keepeth Israel shall neither slumber nor sleep.", prayer = "Father, You do not sleep, so I can. Watch over my home tonight. Amen."),
    DailyPrayer(ref = "1 Peter 5:7", title = "Hand It Over", verse = "Casting all your care upon him; for he careth for you.", prayer = "Lord, before I sleep, I give You the worry I would otherwise take to bed. Amen."),
